function ic(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.wave}"/></svg>`}
function btn(label,action,val='',style=''){return `<button class="btn ${style}" data-action="${action}" data-value="${esc(val)}">${label}</button>`}
function ib(name,action,val='',label='',extra=''){return `<button class="icon-btn ${extra}" data-action="${action}" data-value="${esc(val)}" aria-label="${esc(label||name)}">${ic(name)}</button>`}
function linkrow(title,desc,icon,action,val,trail='›'){return `<div class="list-row">${ic(icon)}<button class="list-link" data-action="${action}" data-value="${esc(val)}"><h4>${esc(title)}</h4><p>${esc(desc)}</p></button><span class="chevron">${trail}</span></div>`}
function section(title,action='',label='查看全部',val=''){return `<div class="section-title"><h3>${title}</h3>${action?`<button class="text-btn" data-action="${action}" data-value="${esc(val)}">${label} ${ic('arrow')}</button>`:''}</div>`}
function top(title='',right=''){return `<div class="topbar">${ib('back','back','','返回')}<span class="small">${title}</span><div class="row">${right||ib('info','sheet','boundary','模型说明')}</div></div>`}
function heading(title,caption,action='nav',val='settings',icon='settings'){return `<div class="page-head"><div><h1>${title}</h1><span class="caps">${caption}</span></div>${ib(icon,action,val,icon==='plus'?'添加':'设置')}</div>`}
function notice(text,style=''){return `<div class="notice ${style}">${text}</div>`}
function toggle(label,desc,key,on){return `<div class="toggle-row"><div class="grow"><b>${label}</b><p>${desc}</p></div><button class="switch ${on?'on':''}" data-action="toggle" data-value="${key}" role="switch" aria-checked="${!!on}" aria-label="${label}"></button></div>`}
function slider(label,key,value,min=0,max=100,step=1,unit='%',help=''){return `<div class="field"><div class="range-label"><label for="r-${key}" style="margin:0;color:var(--ink)">${label}</label><output id="o-${key}">${value}${unit}</output></div><input id="r-${key}" type="range" data-bind="${key}" data-unit="${unit}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}">${help?`<div class="tiny muted">${help}</div>`:''}</div>`}
function seg(options,selected,action){return `<div class="segments">${options.map(([id,name])=>`<button class="${String(id)===String(selected)?'active':''}" data-action="${action}" data-value="${id}">${name}</button>`).join('')}</div>`}
function empty(title,text,action='nav',val='studio',label='创建自己的节奏'){return `<div class="empty">${ic('leaf')}<h3>${title}</h3><p>${text}</p>${btn(label,action,val,'secondary')}</div>`}
