const KEY='pulse_loom_full_v06';let storageOK=true,persistError='',store;
try{let raw=localStorage.getItem(KEY);if(!raw){raw=localStorage.getItem('pulse_loom_full_v05')||localStorage.getItem('pulse_loom_full_v04');if(raw)localStorage.setItem(KEY,raw);}store={...defaults(),...(raw?JSON.parse(raw):{})};for(const k of ['custom','favorites','history','routines','mixes','notes'])if(!Array.isArray(store[k]))throw Error('shape');if(!THEMES.some(t=>t.id===store.theme))store.theme='blush';if(!['auto','light','dark'].includes(store.appearance))store.appearance='auto';}catch(e){store=defaults();persistError='浏览器存储不可用或数据格式异常。本次使用内存，原有数据未清除。';storageOK=false;}
function persist(){if(!storageOK)return false;try{store.savedAt=Date.now();localStorage.setItem(KEY,JSON.stringify(store));return true}catch(e){storageOK=false;persistError='本地保存空间不足；当前修改仍保留在内存，可导出备份。';toast(persistError);return false}}
