const allPatterns=()=>[...PRESETS,...store.custom];
const pattern=id=>allPatterns().find(p=>p.id===id)||PRESETS[1];
const theme=id=>THEMES.find(t=>t.id===(id||store.theme))||THEMES[0];
const activePattern=()=>S.session?.pattern||pattern(store.lastPattern||'p02');
function applyTheme(id=store.theme){
 const t=theme(id), c=palette(id), dark=isDarkAppearance(), appearance=dark?'dark':'light';
 const root=document.documentElement, device=$('#device');
 // The document, safe areas and the simulated iPhone share one appearance.
 [root,device].forEach(el=>{
  colorKeys.forEach((k,i)=>el.style.setProperty('--'+k,c[i]));
  el.style.setProperty('--danger',dark?'#f1a4b1':'#a0414f');
  el.style.setProperty('--elevated',dark?c[2]:c[1]);
  el.style.setProperty('--shadow',dark?'0 16px 40px #00000028':'0 16px 40px #99697d10');
  el.dataset.appearance=appearance;el.style.colorScheme=appearance;
 });
 device.classList.toggle('reduced',store.reduced);device.classList.toggle('large-text',store.largeText);
 // Safari/browser chrome adopts the same background when supported. No native APIs.
 const chrome=document.querySelector('meta[name="theme-color"]');if(chrome)chrome.content=c[0];
 document.body.style.removeProperty('background');
 if($('#sideAppearance')&&!$('#sideAppearance').children.length)$('#sideAppearance').innerHTML=appearanceControls();
 $$('[data-action="appearance"]').forEach(b=>{const on=b.dataset.value===store.appearance;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
 $$('[data-appearance-status]').forEach(el=>{el.textContent=`当前：${dark?'深色':'浅色'} · ${store.appearance==='auto'?'随系统自动切换':'已固定，不随系统变化'}`;});
 $$('[data-theme-swatch]').forEach(el=>{const v=palette(el.dataset.themeSwatch);colorKeys.forEach((k,i)=>el.style.setProperty('--'+k,v[i]));el.style.background=v[0];});
 $$('[data-palette-chip]').forEach(el=>el.style.background=c[Number(el.dataset.paletteChip)]);
 $('#sideThemes').innerHTML=THEMES.slice(0,2).map(t=>`<button data-action="quickTheme" data-value="${t.id}" style="background:${palette(t.id)[4]}" aria-label="切换${t.cn}皮肤"></button>`).join('');
}

let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2700)}
function page(body){return `<div class="page">${body}</div>`}
function meta(){return SCREENS.find(s=>s[0]===S.route)||SCREENS[0]}
function nav(route,opts={}){
 if(!SCREENS.some(s=>s[0]===route))return toast('未找到该页面');
 if(S.route==='record'&&route!=='record')endRecord();if(S.route==='xy'&&route!=='xy')endXY();
 if(S.route==='capability'&&route!=='capability'){clearTimeout(S.capTimer);if(S.cap==='testing')S.cap='ready';}
 if(S.route==='themepreview'&&route!=='themepreview')applyTheme();
 if(S.session?.kind==='preview'&&route!==S.route)stopSession('preview_close',false);
 if(['editor','curve','record','xy','premium','capability'].includes(route))pauseAll('进入'+meta()[2],false);
 if(route==='editor'&&!S.draft)newDraft('basic');if(route==='curve'&&!S.draft)newDraft('curve');
 if(route==='routineedit'&&!S.routineDraft)newRoutine();
 if(opts.reset)S.stack=[];else if(!opts.replace&&route!==S.route)S.stack.push(S.route);
 S.route=route;S.modal=null;render();$('#app').scrollTop=0;
}
function back(){if(S.modal)return closeSheet();if(['editor','curve'].includes(S.route)&&S.editDirty)return showSheet('leaveEditor');let dest=S.stack.pop()||'home';nav(dest,{replace:true});}
function drawWave(p=activePattern(),mini=false){let arr=values(p,100);let path=arr.map((x,i)=>`${i?'L':'M'}${i*3.6} ${48-x*34}`).join(' '),area=`${path}L356 48L0 48Z`;return `<div class="flow-wave ${mini?'compact':''}"><svg viewBox="0 0 360 70" preserveAspectRatio="none" aria-label="设计触觉节奏，非马达测量"><path d="${area}" fill="var(--hero2)" opacity=".3"/><path d="${path}" stroke="var(--accent)" fill="none" stroke-width="1" opacity=".75"/><path d="${arr.map((x,i)=>`${i?'L':'M'}${i*3.6} ${48+x*15}`).join(' ')}" stroke="var(--hero3)" fill="none" stroke-width=".8" opacity=".5"/></svg><span class="playline" data-live="playline"></span></div>`}
function flowingWave(){let paths='';for(let i=0;i<12;i++){paths+=`<path d="M0 ${42+i*.8}C50 ${9+i*2} 67 ${83-i} 117 ${32+i}S195 ${79-i*2} 240 ${37+i*.9} 315 ${15+i*3} 360 ${40+i}" stroke="var(--accent)" stroke-opacity="${.45-i*.026}" stroke-width=".65" fill="none"/>`}return `<div class="flow-wave"><svg data-live="flowShape" viewBox="0 0 360 80" preserveAspectRatio="none">${paths}</svg></div>`}
function values(p,n=80){if(!p)return Array(n).fill(.3);if(p.mode==='curve'&&p.nodes?.length){return Array.from({length:n},(_,i)=>curveValue(p,i/(n-1)*(p.cycle||4000)))}let cycle=patternLength(p)||1000;return Array.from({length:n},(_,i)=>{let t=i/(n-1)*cycle,c=0;for(const e of p.segments||[]){if(t>=c&&t<c+e.duration)return e.gain;c+=e.duration+e.gap}return 0})}
function curveValue(p,t){let ns=p.nodes;if(t<=ns[0].time)return ns[0].value;for(let i=1;i<ns.length;i++){if(t<=ns[i].time){let a=ns[i-1],b=ns[i];return a.value+(b.value-a.value)*(t-a.time)/(b.time-a.time)}}return ns[ns.length-1].value}
function patternLength(p){return p.mode==='curve'?Number(p.cycle):Math.round((p.segments||[]).reduce((s,e)=>s+e.duration+e.gap,0))}
function patternRow(p,kind='normal'){return `<div class="list-row"><div class="thumb">${art(p.art||'orb')}</div><button class="list-link" data-action="detail" data-value="${p.id}"><h4>${esc(p.name)} <span class="tiny muted serif">${esc(p.en||'Your rhythm')}</span></h4><p>${esc(p.category||'自创')} · ${sec(patternLength(p))}一轮 ${p.premium?'· Pro':''}</p></button>${kind==='saved'?ib('dots','manage',p.id,'管理'+p.name):ib('heart','favorite',p.id,'收藏'+p.name,store.favorites.includes(p.id)?'selected':'')}</div>`}
function selectPattern(id){store.lastPattern=id;S.detail=id;persist()}
function transport(action='play',value=''){let playing=S.session?.playing;return `<div class="transport">${ib('skip','nextPattern','-1','上一个节奏')}<button class="play" data-action="${action}" data-value="${value}" aria-label="${playing?'暂停':'播放'}">${ic(playing?'pause':'play')}</button>${ib('stop','stop','','停止所有播放','stop')}</div>`}
function heroMarkup(p,small=false){let orb=theme(S.route==='themepreview'?S.themePreview:store.theme).art==='orb';return `<div class="hero ${orb&&!small?'is-orb':''} ${small?'hero-small':''}"><div class="hero-art">${art(orb?'orb':p.art||'flower')}</div><div class="hero-copy"><div class="caps">${small?'YOUR OWN RHYTHM':'CURRENT PATTERN'}</div><h1>${esc(p.en||p.name)}</h1><p>${esc(p.name)} · ${esc(p.category||'自创')}<br>${small?'':esc(p.desc||'你亲手创造的触觉节奏。')}</p></div>${small?'':`<div class="hero-heart">${ib('heart','favorite',p.id,'收藏当前模式',store.favorites.includes(p.id)?'selected':'')}</div>`}</div>`}
