 const r=S.music.playing?'musicplayer':S.session?.kind==='routine'?'routineplayer':S.session?.kind==='breath'?'breathplayer':S.sound.active&&!S.session?.playing?'sounds':'focus';const name=S.music.playing?S.music.name:S.session?.title||'声景混音';$('#mini').innerHTML=`<div class="mini-player">${ic(S.music.playing?'music':'wave')}<button class="mini-name" data-action="nav" data-value="${r}">${esc(name)}<span class="tiny">点击返回当前会话</span></button>${ib('pause','pauseAll','','暂停')}${ib('stop','stop','','停止')}</div>`;
