// ---------- Playback state and timer; no physical vibration ----------
let pausedMain=null;
function elapsed(s){return s?(s.elapsed+(s.playing?(performance.now()-s.anchor)/1000:0)):0;}
function addHistory(name,kind,seconds,reason){if(!store.historyEnabled||seconds<=0)return;store.history.unshift({id:uid(),name,kind,seconds:Math.round(seconds),reason,at:Date.now()});store.history=store.history.filter(h=>Date.now()-h.at<30*86400000).slice(0,100);persist();}
function startSession(p,kind='pattern',opts={}){
 if(S.output!=='ok'){pauseAll('故障',false);showSheet('fault');return false;}
 if(p?.premium&&!store.pro&&kind!=='preview')return gate('这个节奏属于Pro内容。','基础播放与短时预览保持可用。',()=>startSession(p,kind,opts));
 if(kind==='preview'&&S.session&&S.session.kind!=='preview'){pauseSession();pausedMain=S.session;S.session=null;}else if(S.session)stopSession('切换内容',false);
 if(S.music.playing)pauseMusic();
 const limit=kind==='preview'?Math.min(8,patternLength(p)/1000):opts.limit||store.timer;
 S.session={id:uid(),kind,pattern:p||pattern('p02'),title:opts.title||p?.name||'节奏会话',limit:clamp(limit,.1,600),remaining:clamp(limit,.1,600),elapsed:0,anchor:performance.now(),playing:true,gain:opts.gain??store.gain,speed:store.speed,ended:false};
 if(p&&!p.loop&&kind==='pattern'){S.session.limit=Math.min(S.session.limit,patternLength(p)/1000/store.speed);S.session.remaining=S.session.limit;}
 render();return true;
}
function pauseSession(){let s=S.session;if(!s||!s.playing)return;s.elapsed=Math.min(s.limit,elapsed(s));s.remaining=Math.max(0,s.limit-s.elapsed);s.playing=false;s.pausedAt=performance.now();}
function stopSession(reason='手动停止',complete=false){let s=S.session;if(!s)return;let played=Math.min(s.limit,elapsed(s));s.playing=false;S.session=null;if(s.kind!=='preview'){addHistory(s.title,s.kind,played,reason);S.lastSummary={name:s.title,seconds:played};}else if(pausedMain){S.session=pausedMain;pausedMain=null;S.session.playing=false;S.session.pausedAt=performance.now();}
 if(complete&&s.kind!=='preview'){stopSound();showSheet('complete');}renderMini();
}
function resumeSession(){let s=S.session;if(!s)return startSession(activePattern());if(S.output!=='ok')return showSheet('fault');if(s.pattern?.premium&&!store.pro&&s.kind!=='preview')return gate('需要Pro内容权限。','当前会话保留在暂停状态。',()=>resumeSession());if(s.remaining<=0)return startSession(s.pattern,s.kind,{limit:s.limit});if(s.playing){pauseSession();}else{if(S.music.playing)pauseMusic();s.anchor=performance.now();s.playing=true;s.pausedAt=null;}render();}
function stopAll(reason='手动停止',complete=false){endRecord();endXY();pausedMain=null;stopSession(reason,complete);stopMusic(true,reason);stopSound();S.editorPreview=false;render();}
function pauseAll(reason='暂停',notify=true){pauseSession();pauseMusic();stopSound();endRecord();endXY();renderMini();if(notify)toast(reason+'，由你点击继续。');}
function newRoutine(silent=false){S.routineDraft={id:uid(),name:'',items:[{pattern:'p02',seconds:60,gain:45},{pattern:'p04',seconds:60,gain:50},{pattern:'p12',seconds:60,gain:35}],fade:1,sound:false};return S.routineDraft;}
function validateRoutine(r){if(!r.name.trim())return '请填写组合名称';if(!r.items.length||r.items.length>12)return '组合需要1–12段';if(r.items.some(i=>!Number.isFinite(i.seconds)||i.seconds<15||i.seconds>300))return '每段须为15–300秒';if(r.items.reduce((s,i)=>s+i.seconds,0)>600)return '组合总长不得超过10分钟';return ''}
function playRoutine(r){if(!r)return;let err=validateRoutine(r);if(err)return toast(err);if(!store.pro&&r.items.some(i=>pattern(i.pattern).premium))return gate('编排包含Pro预设。','组合内容已保留；可以修改为免费预设。',()=>playRoutine(r));S.queue=clone(r);S.routineIndex=0;startSession(pattern(r.items[0].pattern),'routine',{limit:r.items.reduce((s,i)=>s+i.seconds,0),gain:r.items[0].gain,title:r.name});if(r.sound){if(!S.sound.levels.some(n=>n>0))S.sound.levels=[15,5,0];startSound();}nav('routineplayer');}
function startBreath(){let b=S.breath;startSession(pattern('p04'),'breath',{limit:b.minutes*60,title:'呼吸时刻'});nav('breathplayer');}
// ---------- Real local Web Audio; analysis drives only visual haptic model ----------
let audioCtx=null,soundNodes=[],soundGeneration=0;
function ctx(){if(!audioCtx){const C=window.AudioContext||window.webkitAudioContext;if(!C)throw Error('当前浏览器不支持Web Audio');audioCtx=new C();}return audioCtx;}
