async function setMusicBuffer(buffer,name,source,generation){if(generation!==S.music.generation)return;if(buffer.duration>.05&&buffer.duration<=600){const a=analyseBuffer(buffer);Object.assign(S.music,{buffer,name,source,duration:buffer.duration,env:a.env,onsets:a.onsets,bpm:a.bpm,status:'ready',offset:0,trialUsed:0,error:''});S.music.config={...S.music.config,from:0,to:buffer.duration};if(S.pendingMix){S.music.config={...S.music.config,...clone(S.pendingMix.config)};S.music.config.from=clamp(S.music.config.from,0,buffer.duration-.1);S.music.config.to=clamp(S.music.config.to,S.music.config.from+.1,buffer.duration);S.pendingMix=null;}if(['music','musicplayer','analysis'].includes(S.route))render();}else throw Error('音频长度须大于0秒且不超过10分钟');}
async function importMusicFile(file){if(!file)return;const m=S.music;stopAll('更换音频');const generation=++m.generation;Object.assign(m,{status:'loading',name:file.name,error:'',buffer:null});nav('music',{replace:true});try{if(file.size>30*1024*1024)throw Error('文件大于30MB，请选择较短的音频');let c=ctx();let raw=await file.arrayBuffer();let b=await c.decodeAudioData(raw);await setMusicBuffer(b,file.name,'file',generation);}catch(e){if(generation!==m.generation)return;m.status='error';m.error='无法解码该音频：'+e.message+'。可换用完整、未受保护的MP3或WAV文件。';if(['music','musicplayer','analysis'].includes(S.route))render();}}
async function demoMusic(kind){stopAll('更换音频');const m=S.music,generation=++m.generation;m.status='loading';m.name=kind==='mist'?'Mist Waltz':'Petal Steps';m.buffer=null;nav('music',{replace:true});try{let c=ctx();const sr=22050,duration=48,b=c.createBuffer(1,sr*duration,sr),d=b.getChannelData(0),beat=kind==='mist'?.8:.6,notes=kind==='mist'?[220,261.63,329.63,293.66]:[261.63,329.63,392,349.23];let seed=731;for(let i=0;i<d.length;i++){let t=i/sr,p=t%beat,nb=Math.floor(t/(beat*2))%notes.length;seed=(seed*1664525+1013904223)>>>0;let noise=(seed/4294967296*2-1);let kick=.3*Math.exp(-p*22)*Math.sin(2*Math.PI*(58*p+2.2*(1-Math.exp(-p*18))));let hat=.035*Math.exp(-(t%(beat/2))*95)*noise;let env=Math.min(1,t/2)*Math.min(1,(duration-t)/2),note=.075*(Math.sin(2*Math.PI*notes[nb]*t)+.45*Math.sin(2*Math.PI*notes[nb]*2*t))*Math.exp(-(t%(beat*2))*1.4);d[i]=env*(kick+hat+note);}await setMusicBuffer(b,m.name,'demo:'+kind,generation);}catch(e){m.status='error';m.error=e.message;render();}}
function musicPosition(){const m=S.music;return clamp(m.playing?m.offset+(ctx().currentTime-m.startAt):m.offset,0,m.duration);}
function disconnectMusicSource(){if(S.music.sourceNode){try{S.music.sourceNode.stop();S.music.sourceNode.disconnect();}catch(e){}S.music.sourceNode=null;}if(S.music.master){S.music.master.disconnect();S.music.master=null;}}
function pauseMusic(){let m=S.music;m.playRequest++;if(!m.playing)return;let pos=musicPosition();m.trialUsed+=(ctx().currentTime-m.startAt);m.totalPlayed=(m.totalPlayed||0)+(ctx().currentTime-m.startAt);m.offset=pos;m.playing=false;disconnectMusicSource();}
function stopMusic(reset=false,reason='停止音乐'){let m=S.music;pauseMusic();if(reset){if(m.totalPlayed>0)addHistory(m.name,'music',m.totalPlayed,reason);m.totalPlayed=0;m.offset=m.config.from||0;}renderMini();}
async function playMusic(){const m=S.music;if(!m.buffer)return nav('sources');if(m.playing){pauseMusic();render();return}if(!store.pro&&m.trialUsed>=60){showSheet('trial');return}if(S.output!=='ok'){showSheet('fault');return}if(!(m.config.to>m.config.from))return toast('结束位置必须晚于开始位置');pauseSession();stopSound();const request=++m.playRequest;try{const c=await readyAudio();if(!m.buffer||request!==m.playRequest)return;m.offset=clamp(m.offset,m.config.from,m.config.to);if(m.offset>=m.config.to-.01)m.offset=m.config.from;disconnectMusicSource();m.sourceNode=c.createBufferSource();m.sourceNode.buffer=m.buffer;m.master=c.createGain();m.master.gain.value=m.config.volume/100;m.sourceNode.connect(m.master);m.master.connect(c.destination);m.startAt=c.currentTime;m.sourceNode.start(0,m.offset);m.playing=true;render();}catch(e){m.playing=false;toast('音频播放失败：'+e.message)}}
function seekMusic(n){let was=S.music.playing;pauseMusic();S.music.offset=clamp(n,S.music.config.from,S.music.config.to);if(was)playMusic();else updateLive();}
function mappedLevel(){let m=S.music,t=musicPosition()-m.config.offset/1000,ix=Math.floor(t/.02),energy=t<0?0:(m.env[ix]||0),power=energy*(.5+m.config.sensitivity/55);if(m.config.mapping==='beats'){let hit=m.onsets.findLast?.(b=>b.time<=t)||[...m.onsets].reverse().find(b=>b.time<=t);power=hit?hit.value*Math.exp(-(t-hit.time)*(m.config.texture==='smooth'?9:22))*(.5+m.config.sensitivity/55):0;}else if(m.config.texture==='smooth'){let vals=m.env.slice(Math.max(0,ix-5),Math.max(0,ix)+1);power=vals.length?vals.reduce((a,b)=>a+b,0)/vals.length*(.5+m.config.sensitivity/55):0;}else if(m.config.texture==='crisp')power=power>.35?Math.min(1,power*1.25):0;
 if(m.config.mapping==='blend'){let p=pattern(m.config.overlay==='none'?'p02':m.config.overlay),a=values(p,100),v=a[Math.floor((t%(patternLength(p)/1000))/(patternLength(p)/1000)*100)]||0;let mix=m.config.overlayMix/100;power=power*(1-mix)+v*mix;}return clamp(power*m.config.gain/100,0,1);}
async function startSound(){const request=++soundGeneration;try{let c=await readyAudio();if(request!==soundGeneration)return;stopSound();if(!S.sound.levels.some(x=>x>0))S.sound.levels=[15,5,0];soundNodes=[];for(let i=0;i<3;i++){let node,filter=null;if(i<2){let b=c.createBuffer(1,c.sampleRate*3,c.sampleRate),a=b.getChannelData(0),last=0;for(let j=0;j<a.length;j++){let v=Math.random()*2-1;last=(last+.02*v)/1.02;a[j]=i===0?v*.11:last*.9;}node=c.createBufferSource();node.buffer=b;node.loop=true;filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=i===0?2800:500;node.connect(filter);}else{node=c.createOscillator();node.type='sine';node.frequency.value=110;}let gain=c.createGain();gain.gain.value=S.sound.levels[i]/100*(i===2?.055:.65);(filter||node).connect(gain);gain.connect(c.destination);node.start();soundNodes.push({node,filter,gain,index:i});}S.sound.active=true;render();}catch(e){toast('声景无法播放：'+e.message)}}
function stopSound(){soundGeneration++;for(const n of soundNodes){try{n.node.stop();n.node.disconnect();n.filter?.disconnect();n.gain.disconnect()}catch(e){}}soundNodes=[];S.sound.active=false;}
function adjustSound(){for(const n of soundNodes)n.gain.gain.value=S.sound.levels[n.index]/100*(n.index===2?.055:.65);}
// ---------- Touch recording and XY recording ----------
function beginRecord(){pauseAll('录制',false);S.record={active:true,events:[],start:performance.now(),down:null,pointer:null,elapsed:0};render();}
function recordDown(id){let r=S.record;if(!r.active)return toast('先点击“开始录制”');if(r.down!==null)return;if(r.events.length>=128)return endRecord();r.down=performance.now();r.pointer=id;$('#recordPad')?.classList.add('pressed');}
function recordUp(id){let r=S.record;if(r.down===null||r.pointer!==id)return;let end=performance.now(),start=Math.max(0,(r.down-r.start)/1000),duration=Math.min(10,(end-r.down)/1000,30-start);if(duration>0)r.events.push({start,duration:Math.max(.02,duration)});r.down=null;r.pointer=null;$('#recordPad')?.classList.remove('pressed');updateLive();}
function endRecord(){let r=S.record;if(!r.active)return;if(r.down!==null)recordUp(r.pointer);r.elapsed=Math.min(30,(performance.now()-r.start)/1000);r.active=false;}
function recordToPattern(){let r=S.record;if(!r.events.length)throw Error('还没有有效触碰');let first=r.events[0].start,segments=r.events.map((e,i)=>{let next=r.events[i+1],gap=next?Math.max(0,next.start-e.start-e.duration):.15;let dur=Math.round(e.duration*1000);return {duration:dur,gap:Math.round(gap*1000),gain:.5,sharp:.25,type:dur<50?'transient':'continuous'}});let total=segments.reduce((n,e)=>n+e.duration+e.gap,0);if(total>30000)segments.at(-1).gap=Math.max(0,segments.at(-1).gap-(total-30000));return {...clone(S.draft||newDraft('record',true)),id:S.draft?.id||uid(),name:S.draft?.name||'我的敲击节奏',mode:'recorded',segments,cycle:segments.reduce((n,e)=>n+e.duration+e.gap,0),nodes:[],origin:'custom',premium:false,derivedFrom:null};}
function endXY(){if(S.xy.active){sampleXY(true);S.xy.active=false;}S.xy.down=false;S.xy.pointer=null;}
function sampleXY(force=false){let x=S.xy;if(!x.active)return;let t=Math.min(30,(performance.now()-x.start)/1000);let last=x.points.at(-1);if(force||!last||t-last.time>=.23){if(x.points.length<128)x.points.push({time:t,gain:x.y,sharp:x.x});}}
function xyToPattern(){endXY();if(S.xy.points.length<2)throw Error('请记录至少两个时刻的变化');let pts=S.xy.points;let segs=pts.slice(0,-1).map((p,i)=>({duration:Math.max(1,Math.round((pts[i+1].time-p.time)*1000)),gap:0,gain:p.gain,sharp:p.sharp,type:'continuous'}));let d={...clone(S.draft||newDraft('xy',true)),id:S.draft?.id||uid(),name:S.draft?.name||'我的指尖流动',mode:'recorded',segments:segs,nodes:[],origin:'custom',premium:false,derivedFrom:null};d.cycle=patternLength(d);return d;}
function updateLive(){let s=S.session;if(s){let used=elapsed(s);s.remaining=Math.max(0,s.limit-used);if(s.playing&&used>=s.limit){stopSession('定时完成',true);render();s=S.session;}else if(!s.playing&&s.pausedAt&&performance.now()-s.pausedAt>300000){stopSession('暂停超过5分钟',false);render();s=null;}if(s?.kind==='routine'&&S.queue){let total=0,idx=0;for(let i=0;i<S.queue.items.length;i++){total+=S.queue.items[i].seconds;idx=i;if(used<total)break}if(idx!==S.routineIndex){S.routineIndex=idx;s.pattern=pattern(S.queue.items[idx].pattern);s.gain=S.queue.items[idx].gain;if(S.route==='routineplayer')render();}}}
 const set=(key,v)=>$$(`[data-live="${key}"]`).forEach(el=>el.textContent=v);
 set('remaining',fmt(S.session?.remaining??store.timer));set('status',S.session?.playing?'正在演示':S.session?'已暂停':'点击开始');set('timerLabel',(store.timer/60)+' 分钟');
 if(S.session?.playing){let p=S.session.pattern,phase=(elapsed(S.session)*store.speed%(patternLength(p)/1000))/(patternLength(p)/1000);$$('[data-live="playline"]').forEach(el=>el.style.left=phase*100+'%');}

 if(S.session?.playing){let ss=S.session,pp=ss.pattern,aa=values(pp,100),phase=(elapsed(ss)*store.speed%(patternLength(pp)/1000))/(patternLength(pp)/1000),level=(aa[Math.floor(phase*99)]||0)*(ss.gain/100);let fi=(pp.fadeIn||0)/1000,fo=(pp.fadeOut||0)/1000;if(ss.kind==='routine'){fi=S.queue?.fade||0;fo=fi;}if(fi)level*=Math.min(1,elapsed(ss)/fi);if(fo)level*=Math.min(1,ss.remaining/fo);$$('[data-live="flowShape"]').forEach(el=>{el.style.transform='scaleY('+(0.4+level*.9)+')';el.style.transformOrigin='center';el.style.opacity=.45+store.sharp/100*.5;});}else{$$('[data-live="flowShape"]').forEach(el=>{el.style.transform='';el.style.opacity='';});}
 const m=S.music;if(m.playing){let pos=musicPosition();if(pos>=m.config.to-.015||pos>=m.duration-.015){stopMusic(false,'歌曲结束');S.lastSummary={name:m.name,seconds:m.totalPlayed||m.duration};if(m.totalPlayed>0){addHistory(m.name,'music',m.totalPlayed,'歌曲结束');m.totalPlayed=0;}if(['music','musicplayer'].includes(S.route))render();}else if(!store.pro&&m.trialUsed+ctx().currentTime-m.startAt>=60){pauseMusic();render();showSheet('trial');}}
 set('musicPosition',fmt(musicPosition()));let mp=$('#musicSeek');if(mp&&document.activeElement!==mp)mp.value=musicPosition();$$('[data-live="musicLine"]').forEach(el=>el.style.left=(m.duration?musicPosition()/m.duration*100:0)+'%');let lv=m.playing?mappedLevel():0;set('hapticLevel',Math.round(lv*100)+'%');$$('[data-live="meter"]').forEach(el=>el.style.width=lv*100+'%');
 let r=S.record;if(r.active){r.elapsed=Math.min(30,(performance.now()-r.start)/1000);if(r.down!==null&&(performance.now()-r.down)/1000>=10)recordUp(r.pointer);if(r.elapsed>=30||r.events.length>=128){endRecord();if(S.route==='record')render();}}set('recordTime',fmt(r.elapsed)+' / 00:30');set('recordCount',r.events.length+' 个触碰');
 if(S.xy.active){sampleXY();let sec=(performance.now()-S.xy.start)/1000;set('xyTime',fmt(sec));if(sec>=30||S.xy.points.length>=128){endXY();if(S.route==='xy')render();}}set('xyCount',S.xy.points.length+' 个采样点');
 if(S.session?.kind==='breath'){let b=S.breath,cy=b.in+b.hold+b.out,ph=elapsed(S.session)%cy,label=ph<b.in?'吸气':ph<b.in+b.hold?'自然停留':'呼气',cnt=ph<b.in?b.in-ph:ph<b.in+b.hold?b.in+b.hold-ph:cy-ph;set('breathPhase',label);set('breathCount',Math.ceil(cnt)+'秒 · 按自己的节奏');$$('[data-live="breathRing"]').forEach(el=>{let v=ph<b.in?.75+ph/b.in*.25:ph<b.in+b.hold?1:1-(ph-b.in-b.hold)/b.out*.25;el.style.transform=`scale(${v})`;});}
}
