function routineJump(index){if(!S.queue)return;let target=S.queue.items.slice(0,index).reduce((n,i)=>n+i.seconds,0);if(!S.session||S.session.kind!=='routine')playRoutine(S.queue);if(!S.session)return;S.session.elapsed=target;S.session.anchor=performance.now();S.session.remaining=S.session.limit-target;S.routineIndex=index;S.session.pattern=pattern(S.queue.items[index].pattern);S.session.gain=S.queue.items[index].gain;render();}
function handleToggle(key){
 if(key==='draftLoop'){remember();S.draft.loop=!S.draft.loop;draftChanged();}
 else if(key==='routineSound')S.routineDraft.sound=!S.routineDraft.sound;
 else if(key==='remoteConsent'){S.remote.consent=!S.remote.consent;if(!S.remote.consent)stopAll('许可撤回');}
 else if(key==='widgetPrivate')S.widget.private=!S.widget.private;
 else if(key in store){store[key]=!store[key];persist();}
 render();
}
ACTIONS.toggle=handleToggle;
