let rangeUndoStarted=new Set();
function bind(el,commit=false){const k=el.dataset.bind;if(!k)return;let n=Number(el.value),out=$('#o-'+k);if(out)out.textContent=el.value+(el.dataset.unit||'');
 if(k==='name'){store.name=el.value.slice(0,24);persist();return}
 if(k==='search'){S.search=el.value;$('#libraryResults').innerHTML=libraryResults();return}
 if(['gain','speed','sharp','watchGain'].includes(k)){let target=k==='watchGain'?'gain':k;store[target]=clamp(n,target==='speed'?.5:0,target==='speed'?2:100);if(S.session)S.session.gain=S.session.kind==='remote'?Math.min(store.gain,S.remote.level):store.gain;persist();return}
 if(k==='timerInput'){S.timerInput=n;return}
 if(k==='draftName'){if(!rangeUndoStarted.has(k)){remember();rangeUndoStarted.add(k)}S.draft.name=el.value;draftChanged();if(commit)rangeUndoStarted.delete(k);return}
 if(k.startsWith('e_')){if(!rangeUndoStarted.has(k)){remember();rangeUndoStarted.add(k)}let prop=k.slice(2),ev=S.draft.segments[S.selected];if(ev)ev[prop]=prop==='gain'||prop==='sharp'?n/100:n;draftChanged();if(commit){rangeUndoStarted.delete(k);if(typeof uxUpdateEditor==='function')uxUpdateEditor();else render()}return}
 if(['curveLength','curveSharp','fadeIn','fadeOut'].includes(k)){if(!rangeUndoStarted.has(k)){remember();rangeUndoStarted.add(k)}if(k==='curveLength'){let old=S.draft.cycle;S.draft.cycle=n*1000;S.draft.nodes=S.draft.nodes.map(p=>({...p,time:p.time*S.draft.cycle/old}));}else if(k==='curveSharp')S.draft.sharp=n/100;else S.draft[k]=n;draftChanged();if(commit){rangeUndoStarted.delete(k);if(typeof uxUpdateEditor==='function')uxUpdateEditor();else render()}return}
 if(k==='xygain'||k==='xysharp'){if(k==='xygain')S.xy.y=clamp(n,0,100)/100;else S.xy.x=clamp(n,0,100)/100;updateXYDot();return}
 if(k.startsWith('m_')){let prop=k.slice(2);S.music.config[prop]=n;if(prop==='volume'&&S.music.master)S.music.master.gain.value=n/100;return}
 if(k==='musicSeek'){if(commit)seekMusic(n);return}
 if(k==='musicFrom'){S.music.config.from=n;return}if(k==='musicTo'){S.music.config.to=n;return}
 if(k==='musicOverlay'){S.music.config.overlay=el.value;return}
 if(/^sound[012]$/.test(k)){S.sound.levels[Number(k.slice(-1))]=clamp(n,0,100);adjustSound();return}
 if(['breathIn','breathOut','breathHold','breathMinutes'].includes(k)){let prop={breathIn:'in',breathOut:'out',breathHold:'hold',breathMinutes:'minutes'}[k];S.breath[prop]=clamp(n,prop==='hold'?0:prop==='minutes'?1:2,prop==='out'?12:prop==='hold'?8:10);S.breath.preset='custom';return}
 if(k==='routineName'){S.routineDraft.name=el.value;return}if(k==='routineFade'){S.routineDraft.fade=clamp(n,0,3);return}
 if(k==='routineItemSeconds'){S.routineDraft.items[S.routineEditIndex].seconds=n;return}if(k==='routineItemGain'){S.routineDraft.items[S.routineEditIndex].gain=clamp(n,0,100);return}
 if(k==='remoteCode'){S.remote.code=el.value.toUpperCase();return}if(k==='remoteLimit'){S.remote.level=clamp(n,0,100);if(S.session?.kind==='remote')S.session.gain=Math.min(S.session.gain,S.remote.level);return}if(k==='remotePattern'){S.remote.pattern=el.value;return}
 if(k==='widgetPattern'){S.widget.pattern=el.value;render();return}
}
function updateXYDot(){let d=$('#xyDot');if(d){d.style.left=S.xy.x*100+'%';d.style.top=(1-S.xy.y)*100+'%';}let x=$('#r-xysharp'),y=$('#r-xygain');if(x)x.value=Math.round(S.xy.x*100);if(y)y.value=Math.round(S.xy.y*100);if($('#o-xysharp'))$('#o-xysharp').textContent=Math.round(S.xy.x*100)+'%';if($('#o-xygain'))$('#o-xygain').textContent=Math.round(S.xy.y*100)+'%';}
function pointerXY(e){let box=$('#xyPad').getBoundingClientRect();S.xy.x=clamp((e.clientX-box.left)/box.width,0,1);S.xy.y=1-clamp((e.clientY-box.top)/box.height,0,1);updateXYDot();}
let curveDrag=null;
function curveMove(e){if(curveDrag==null)return;let svg=$('#curveSvg');if(!svg)return;let rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*360,y=(e.clientY-rect.top)/rect.height*190;let ns=S.draft.nodes,i=curveDrag,min=i?ns[i-1].time+10:0,max=i<ns.length-1?ns[i+1].time-10:S.draft.cycle;ns[i].time=clamp((x-12)/336*S.draft.cycle,min,max);ns[i].value=clamp((170-y)/145,0,1);S.nodeSelected=i;let circle=svg.querySelector(`[data-node="${i}"]`);circle?.setAttribute('cx',String(12+ns[i].time/S.draft.cycle*336));circle?.setAttribute('cy',String(170-ns[i].value*145));}
function validAction(action,value){const fn=ACTIONS[action];if(!fn){console.error('Missing action',action);toast('这个动作尚未定义：'+action);return}try{const result=fn(value);if(result?.catch)result.catch(e=>{console.error(e);toast('操作未完成：'+e.message)})}catch(e){console.error(e);toast('操作未完成：'+e.message)}}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a&&!a.disabled){e.preventDefault();validAction(a.dataset.action,a.dataset.value||'');return}if(e.target.matches('[data-dismiss]'))closeSheet();});
document.addEventListener('input',e=>{if(e.target.matches('[data-bind]'))bind(e.target,false)});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-bind]'))bind(el,true);if(el.matches('[data-node-field]')){remember();let i=Number(el.dataset.index),key=el.dataset.nodeField,value=Number(el.value);S.draft.nodes[i][key]=key==='value'?value/100:value;draftChanged();render();}});
document.addEventListener('pointerdown',e=>{const pad=e.target.closest('#recordPad'),xy=e.target.closest('#xyPad');if(pad){if(!S.record.active)return;recordDown(e.pointerId);if(S.record.pointer===e.pointerId)pad.setPointerCapture(e.pointerId);e.preventDefault();}if(xy){if(S.xy.pointer!=null)return;S.xy.pointer=e.pointerId;S.xy.down=true;xy.setPointerCapture(e.pointerId);pointerXY(e);e.preventDefault();}const circle=e.target.closest('[data-node]');if(circle){remember();curveDrag=Number(circle.dataset.node);S.nodeSelected=curveDrag;$('#curveSvg').setPointerCapture(e.pointerId);e.preventDefault();}else if(e.target.id==='curveSvg'&&S.draft?.mode==='curve'){if(S.draft.nodes.length>=64)return toast('最多64节点');let rect=e.target.getBoundingClientRect(),time=clamp(((e.clientX-rect.left)/rect.width*360-12)/336*S.draft.cycle,0,S.draft.cycle),value=clamp((170-(e.clientY-rect.top)/rect.height*190)/145,0,1);if(S.draft.nodes.some(n=>Math.abs(n.time-time)<10))return;remember();S.draft.nodes.push({time,value});S.draft.nodes.sort((a,b)=>a.time-b.time);draftChanged();render();}});
document.addEventListener('pointermove',e=>{if(S.xy.down&&e.pointerId===S.xy.pointer){pointerXY(e);e.preventDefault()}if(curveDrag!=null)curveMove(e)});
document.addEventListener('pointerup',e=>{if(S.record.pointer===e.pointerId)recordUp(e.pointerId);if(S.xy.pointer===e.pointerId){S.xy.down=false;S.xy.pointer=null;}if(curveDrag!=null){curveDrag=null;draftChanged();render()}});
document.addEventListener('pointercancel',e=>{if(S.record.pointer===e.pointerId){recordUp(e.pointerId);endRecord();render()}if(S.xy.pointer===e.pointerId){endXY();render()}if(curveDrag!=null){curveDrag=null;draftChanged();render()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(S.modal)closeSheet();else if(['focus','record','xy'].includes(S.route))back();}if(e.target.id==='recordPad'&&[' ','Enter'].includes(e.key)&&!e.repeat){e.preventDefault();recordDown('keyboard')}
 if(S.modal&&e.key==='Tab'){let focusable=$$('#modalRoot button:not(:disabled), #modalRoot input, #modalRoot select, #modalRoot textarea').filter(el=>el.offsetParent!==null);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}
});
document.addEventListener('keyup',e=>{if([' ','Enter'].includes(e.key)&&S.record.pointer==='keyboard'){e.preventDefault();recordUp('keyboard')}});
