// React without rebuilding the view: preserve unsaved text, scroll, focus,
// modal input, audio position, touch-recording and the single playback session.
const onSystemAppearance=()=>{if(store.appearance==='auto')applyTheme(S.route==='themepreview'?S.themePreview:store.theme);};
if(systemAppearance.addEventListener)systemAppearance.addEventListener('change',onSystemAppearance);
else if(systemAppearance.addListener)systemAppearance.addListener(onSystemAppearance);

